                <div className="pointer-events-auto flex w-full max-w-[400px] flex-col items-center rounded-[28px] border border-white/80 bg-white/92 px-7 py-5 text-center shadow-[0_24px_50px_-30px_rgba(15,23,42,0.45)]">
