"use client";

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { fetchThreads, createThread, deleteThread } from '@/services/apiServices';
import { Pagination, Select, Tabs, Modal, Input, Button, Form, message } from 'antd';
import GifLoader from '@/components/utility/GifLoader';
import Link from 'next/link';
import 'next/image';
import { ClockCircleOutlined, EyeOutlined, MessageOutlined, FireOutlined, EditOutlined } from '@ant-design/icons';
import dayjs from 'dayjs';
import 'dayjs/locale/th';
import TextEditor from '@/components/utility/TextEditor';
import { useAuthStore } from '@/stores/authStore';
import { useUIStore } from '@/stores/uiStore';
import { useEffect } from 'react';

dayjs.locale('th');

const ThreadTypes = [
  { id: 0, name: 'ทั้งหมด', color: 'gray', icon: <FireOutlined /> },
  { id: 1, name: 'สารทุกข์-สุขดิบ', color: 'blue', borderColor: 'border-blue-400', bgColor: 'bg-blue-50', textColor: 'text-blue-600' },
  { id: 2, name: 'เมาท์เรื่องนิยาย', color: 'yellow', borderColor: 'border-yellow-400', bgColor: 'bg-yellow-50', textColor: 'text-yellow-600' },
  { id: 3, name: 'การ์ตูนดีบอกต่อ', color: 'green', borderColor: 'border-green-400', bgColor: 'bg-green-50', textColor: 'text-green-600' },
  { id: 4, name: 'เรื่องหลอนๆสายมืด', color: 'red', borderColor: 'border-red-800', bgColor: 'bg-red-50', textColor: 'text-red-800' }, 
];

// Helper to get type info
const getTypeInfo = (typeId: number) => {
  return ThreadTypes.find(t => t.id === typeId) || ThreadTypes[1];
};

type InitialThreadResponse = Awaited<ReturnType<typeof fetchThreads>>;

interface ThreadsProps {
  initialThreadResponse?: InitialThreadResponse;
}

export default function Threads({ initialThreadResponse }: ThreadsProps) {
  const [activeType, setActiveType] = useState(0);
  const [page, setPage] = useState(1);
  const [sort, setSort] = useState('newest');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [form] = Form.useForm();
  const queryClient = useQueryClient();
  const [messageApi, contextHolder] = message.useMessage();
  const { token } = useAuthStore() as any;
  const { openLoginModal } = useUIStore();
  const [currentUserId, setCurrentUserId] = useState<number | null>(null);

  useEffect(() => {
    if (token) {
      try {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(
          atob(base64)
            .split('')
            .map((c) => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2))
            .join('')
        );
        const decoded = JSON.parse(jsonPayload);
        const uid = decoded.user_id || decoded.id || decoded.sub || decoded.userId;
        setCurrentUserId(Number(uid));
      } catch {
      }
    }
  }, [token]);

  const { data: threadResponse, isLoading } = useQuery({
    queryKey: ['threads', activeType, page, sort],
    queryFn: () => fetchThreads({ 
      page, 
      limit: 9, 
      type: activeType === 0 ? undefined : activeType, 
      sort 
    }),
    initialData: activeType === 0 && page === 1 && sort === 'newest' ? (initialThreadResponse ?? undefined) : undefined,
    staleTime: 60 * 1000,
  });

  const createThreadMutation = useMutation({
    mutationFn: createThread,
    onSuccess: () => {
      messageApi.success('ตั้งกระทู้สำเร็จ');
      setIsModalOpen(false);
      form.resetFields();
      queryClient.invalidateQueries({ queryKey: ['threads'] });
    },
    onError: () => {
      messageApi.error('เกิดข้อผิดพลาดในการตั้งกระทู้');
    },
  });

  const deleteThreadMutation = useMutation({
    mutationFn: deleteThread,
    onSuccess: () => {
      messageApi.success('ลบกระทู้สำเร็จ');
      queryClient.invalidateQueries({ queryKey: ['threads'] });
    },
    onError: () => {
        messageApi.error('เกิดข้อผิดพลาดในการลบกระทู้');
    }
  });

  void deleteThreadMutation;


  const threads = threadResponse?.data?.list || [];
  const pagination = threadResponse?.data?.paginate;

  const handleTypeChange = (key: string) => {
    setActiveType(Number(key));
    setPage(1);
  };

  const handlePageChange = (p: number) => {
    setPage(p);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };
  
  const handleCreateThread = (values: any) => {
    const payload = {
      title: values.title,
      rate: values.rating,
      author: values.penname,
      type: String(values.category),
      tag: Array.isArray(values.tags) ? values.tags.join(',') : values.tags,
      detail: values.content
    };
    createThreadMutation.mutate(payload);
  };

  return (
    <div className="min-h-screen bg-white pb-20">
       {contextHolder}
       <style jsx>{`
        :global(.ant-tabs-tab:hover) {
          color: #dc2626 !important;
        }
        :global(.ant-tabs-tab:hover .ant-tabs-tab-btn) {
          color: #dc2626 !important;
        }
        :global(.ant-tabs-tab:hover svg) {
          fill: #dc2626 !important;
          color: #dc2626 !important;
        }
        :global(.ant-tabs-tab-active .ant-tabs-tab-btn) {
          color: #dc2626 !important;
        }
        :global(.ant-tabs-tab-active) {
          color: #dc2626 !important;
        }
        :global(.ant-tabs-tab-active svg) {
          fill: #dc2626 !important;
          color: #dc2626 !important;
        }
        :global(.ant-tabs-ink-bar) {
          background: #dc2626 !important;
        }
      `}</style>
      
       {/* Modal Create Thread */}
       <Modal
          title={<span className="text-xl font-bold">ตั้งกระทู้</span>}
          open={isModalOpen}
          onCancel={() => setIsModalOpen(false)}
          width={800}
          destroyOnHidden
          footer={[
            <div key="footer" className="flex justify-center gap-4">
               <Button key="cancel" onClick={() => setIsModalOpen(false)} style={{ borderRadius: '20px', padding: '0 30px' }}>
                 ยกเลิก
               </Button>
               <Button key="submit" type="primary" onClick={form.submit} className="bg-[#E53935] hover:bg-[#d32f2f]" style={{ borderRadius: '20px', padding: '0 30px', border: 'none' }}>
                 บันทึก
               </Button>
            </div>
          ]}
       >
         <Form 
           form={form} 
           layout="vertical"
           className="mt-4"
           onFinish={handleCreateThread}
           initialValues={{ rating: 'all' }}
         >
            <Form.Item label="ชื่อกระทู้" name="title" rules={[{ required: true, message: 'กรุณากรอกชื่อกระทู้' }]}>
               <Input placeholder="ชื่อกระทู้" />
            </Form.Item>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               <Form.Item label="นามปากกา" name="penname" rules={[{ required: true, message: 'กรุณากรอกนามปากกา' }]}>
                 <Input placeholder="นามปากกา" />
               </Form.Item>
               <div className="grid grid-cols-2 gap-4">
                  <Form.Item label="ระดับเนื้อหา" name="rating" rules={[{ required: true }]}>
                    <Select options={[
                      { value: 'all', label: 'ทุกวัย' },
                      { value: 'nc', label: 'อายุ 18 ปีขึ้นไป' },
                    ]} />
                  </Form.Item>
                  <Form.Item label="หมวดหมู่" name="category" rules={[{ required: true, message: 'กรุณาเลือกหมวดหมู่' }]}>
                    <Select options={ThreadTypes.filter(t => t.id !== 0).map(t => ({ value: t.id, label: t.name }))} />
                  </Form.Item>
               </div>
            </div>

            <Form.Item label="แท็ก" name="tags" rules={[{ required: true, message: 'กรุณาระบุแท็ก' }]}>
               <Select mode="tags" placeholder="กรุณาระบุแท็ก" />
            </Form.Item>

            <Form.Item label="เนื้อหา" name="content" rules={[{ required: true, message: 'กรุณากรอกเนื้อหา' }]}>
               <TextEditor height={300} />
            </Form.Item>
         </Form>
       </Modal>

       {/* Header Banner - Pinkish Background */}
       <div className="bg-[#FFD1D1] relative h-[250px] md:h-[300px] flex items-center justify-center overflow-hidden mb-8">
          {/* Mascot (Placeholder) */}
          <div className="absolute left-4 md:left-20 bottom-0 w-32 md:w-48 h-32 md:h-48">
              <div className="w-full h-full bg-white rounded-t-full shadow-lg relative">
                 <div className="absolute top-10 left-8 w-4 h-4 bg-black rounded-full"></div>
                 <div className="absolute top-10 right-8 w-4 h-4 bg-black rounded-full"></div>
                 <div className="absolute bottom-8 left-1/2 -translate-x-1/2 w-8 h-4 bg-pink-300 rounded-b-full"></div>
                 <div className="absolute bottom-10 left-4 text-pink-300 text-xl">{'///'}</div>
                 <div className="absolute bottom-10 right-4 text-pink-300 text-xl">{'///'}</div>
              </div>
          </div>
          
          <h1 className="text-4xl md:text-6xl font-bold text-[#E53935] drop-shadow-sm">
            กระทู้
          </h1>

          <div className="absolute right-4 top-4">
             <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center border-2 border-red-500">
               <span className="text-[10px] text-center font-bold leading-tight">Enjoy<br/>Book</span>
             </div>
          </div>
       </div>

       <div className="max-w-[1200px] mx-auto px-4">
          
          {/* Toolbar: Tabs & Sort */}
          <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
             {/* Tabs */}
             <Tabs
                activeKey={String(activeType)}
                onChange={handleTypeChange}
                items={ThreadTypes.map(type => ({
                  key: String(type.id),
                  label: (
                    <span className="flex items-center gap-2 text-base md:text-lg">
                      {activeType === type.id && <span className="text-red-500">◈</span>}
                      {type.name}
                    </span>
                  )
                }))}
                className="w-full md:w-auto flex-1 [&_.ant-tabs-nav]:mb-0"
             />

             {/* Sort & Create Button */}
             <div className="flex items-center gap-3">
               <button 
                 className="flex items-center gap-2 bg-[#E53935] hover:bg-[#d32f2f] text-white px-4 py-1.5 rounded-full font-medium transition-colors shadow-sm text-base"
                 style={{ color: '#ffffff' }}
                 onClick={() => {
                    if (!token) {
                        openLoginModal();
                        return;
                    }
                    setIsModalOpen(true);
                 }}
               >
                  <EditOutlined style={{ color: '#ffffff' }} />
                  <span style={{ color: '#ffffff' }}>ตั้งกระทู้</span>
               </button>

               <Select
                  defaultValue="newest"
                  style={{ width: 160 }}
                  onChange={(val) => setSort(val)}
                  options={[
                    { value: 'newest', label: 'ล่าสุด' },
                    { value: 'view', label: 'ยอดนิยม' },
                    { value: 'oldest', label: 'เก่าสุด' },
                  ]}
                  variant="borderless"
                  className="bg-white border border-gray-200 rounded px-2"
               />
             </div>
          </div>

          {/* Thread List Grid */}
          {isLoading ? (
             <div className="flex justify-center py-20">
               <GifLoader className="w-20 h-20" />
             </div>
          ) : (
            <>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-12">
                 {threads.length > 0 ? (
                   threads.map((thread) => {
                     const typeInfo = getTypeInfo(thread.type);
                     
                     const isOwner = currentUserId && Number(currentUserId) === Number(thread.user_id);

                     return (
                       <div key={thread.topic_id} className="relative group/card">
                         <Link 
                           href={`/thread/${thread.topic_id}`}
                           className="block"
                         >
                         <div 
                           className={`bg-white rounded-xl border-2 p-4 h-[220px] flex flex-col justify-between hover:shadow-lg transition-shadow cursor-pointer ${typeInfo.borderColor} relative`}
                         >
                            {/* Owner Indicator */}
                            {isOwner && (
                                <div className="absolute top-2 right-2 z-10">
                                    <span className="bg-red-100 text-red-600 text-[10px] font-bold px-2 py-0.5 rounded-full border border-red-200">
                                        โพสต์ของฉัน
                                    </span>
                                </div>
                            )}

                           <div>
                              <h3 className={`font-bold text-lg mb-2 truncate ${typeInfo.textColor} pr-16`}>
                                {typeInfo.name}
                              </h3>
                              
                              <div className={`${typeInfo.bgColor} rounded-lg p-3 min-h-[80px]`}>
                                 <h4 className="font-semibold text-gray-800 text-lg mb-1 line-clamp-2">
                                   {thread.title}
                                 </h4>
                                 <p className="text-gray-500 text-sm line-clamp-1">
                                   {/* Description placeholder if API doesn't provide desc */}
                                   {thread.title} ...
                                 </p>
                              </div>
                           </div>
                           
                           <div className="flex items-center justify-between text-gray-400 text-xs mt-4">
                              <div className="flex items-center gap-3">
                                 <div className="flex items-center gap-1">
                                   <EyeOutlined />
                                   <span>{thread.view?.toLocaleString() || 0}</span>
                                 </div>
                                 <div className="flex items-center gap-1">
                                   <MessageOutlined />
                                   <span>{thread.comment_count?.toLocaleString() || 0}</span>
                                 </div>
                              </div>
                              
                              <div className="flex items-center gap-1">
                                 <ClockCircleOutlined />
                                 <span>{dayjs(thread.date_at).format('DD/MM/YYYY')}</span>
                              </div>
                           </div>
                         </div>
                         </Link>

                         {/* Delete Menu Removed - Moved to ThreadDetail */}
                       </div>
                     );
                   })
                 ) : (
                   <div className="col-span-full text-center py-20 text-gray-400">
                      <p className="text-xl">ไม่พบกระทู้ในหมวดหมู่นี้</p>
                   </div>
                 )}
              </div>

              {/* Pagination */}
              {pagination && pagination.totalPages > 1 && (
                 <div className="flex justify-center mb-10">
                    <Pagination 
                      current={page} 
                      total={pagination.total} 
                      pageSize={pagination.limit}
                      onChange={handlePageChange}
                      showSizeChanger={false}
                    />
                 </div>
              )}
            </>
          )}

       </div>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Modal, Progress, App } from 'antd';
import Image from 'next/image';
import Link from 'next/link';
import { Trophy, Award, Target, BookOpen, Coins, Flame, Gift, ChevronRight, X } from 'lucide-react';
import { fetchAchievements, fetchAchievementDetail, claimAchievement } from '@/services/api/achievementApi';
import { useAuthStore } from '@/stores/authStore';
import { useWebsiteStore } from '@/stores/websiteStore';

const conditionLabels: Record<string, { label: string; icon: React.ReactNode; color: string }> = {
  login_streak: { label: 'ล็อกอินต่อเนื่อง', icon: <Flame size={16} />, color: '#F59E0B' },
  read_chapter: { label: 'อ่านตอน', icon: <BookOpen size={16} />, color: '#3B82F6' },
  spend_coin: { label: 'ใช้เหรียญ', icon: <Coins size={16} />, color: '#10B981' },
};

const getConditionInfo = (type: string) => {
  return conditionLabels[type] || { label: type, icon: <Target size={16} />, color: '#6B7280' };
};

export default function AchievementPageClient() {
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [claiming, setClaiming] = useState(false);
  const queryClient = useQueryClient();
  const { notification } = App.useApp();
  const { updateToken } = useAuthStore();
  const { settings } = useWebsiteStore();

  const { data, isLoading } = useQuery({
    queryKey: ['achievements'],
    queryFn: fetchAchievements,
    staleTime: 60000,
    refetchOnWindowFocus: false,
  });

  const { data: detail, isLoading: detailLoading } = useQuery({
    queryKey: ['achievementDetail', selectedId],
    queryFn: () => fetchAchievementDetail(selectedId!),
    enabled: !!selectedId,
    staleTime: 60000,
    refetchOnWindowFocus: false,
  });

  const summary = data?.summary;
  const list = data?.list || [];

  const handleCardClick = (achievementId: number) => {
    setSelectedId(achievementId);
    setIsDetailOpen(true);
  };

  const handleClaim = async (achievementId: number) => {
    setClaiming(true);
    try {
      const res = await claimAchievement(achievementId);

      // Update token if API returns a new one
      let newToken = res?.token ?? res?.data?.token;
      if (typeof newToken === 'object' && newToken?.token) {
        newToken = newToken.token;
      }
      if (newToken && typeof newToken === 'string' && typeof updateToken === 'function') {
        updateToken(newToken);
      }

      notification.success({
        message: res?.message || 'รับรางวัลสำเร็จ!',
        placement: 'topRight',
      });
      // Refetch both list and detail
      queryClient.invalidateQueries({ queryKey: ['achievements'] });
      queryClient.invalidateQueries({ queryKey: ['achievementDetail', achievementId] });
    } catch (err: any) {
      notification.error({
        message: err?.response?.data?.message || 'ไม่สามารถรับรางวัลได้',
        placement: 'topRight',
      });
    } finally {
      setClaiming(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#F4F6F9] py-8 font-primary font-medium">
      <div className="max-w-[1440px] w-full mx-auto px-4 lg:px-[156px]">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 mb-6">
          <Link href="/mprofile" className="text-gray-500 hover:text-[#E33527] transition-colors">ข้อมูลของฉัน</Link>
          <span className="text-gray-400">/</span>
          <span className="text-[#E33527] font-semibold">ความสำเร็จ</span>
        </div>

        {/* Header */}
        <div className="mb-6">
          <h1 className="text-2xl font-bold text-black border-l-4 border-[#E33527] pl-3 m-0">ความสำเร็จ</h1>
        </div>

        {/* Summary Section */}
        {summary && (
          <div className="bg-white rounded-[32px] p-8 mb-10 border border-gray-100 shadow-sm relative overflow-hidden">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-8">
              <div className="flex items-center gap-5">
                <div className="w-16 h-16 bg-red-50 rounded-2xl flex items-center justify-center text-[#E33527]">
                  <Trophy size={32} strokeWidth={1.5} />
                </div>
                <div>
                  <h2 className="text-2xl font-bold text-gray-900 mb-1">ความสำเร็จของฉัน</h2>
                  <p className="text-gray-500 text-sm font-normal">ทำภารกิจสะสมเพื่อรับรางวัลพิเศษและสิทธิประโยชน์</p>
                </div>
              </div>
              
              <div className="flex items-center gap-12">
                <div className="text-center">
                  <p className="text-3xl font-black text-gray-900 tracking-tight">{summary.total_achievements}</p>
                  <p className="text-[10px] uppercase font-bold text-gray-400 tracking-widest mt-1">ทั้งหมด</p>
                </div>
                <div className="w-px h-10 bg-gray-100" />
                <div className="text-center">
                  <p className="text-3xl font-black text-[#E33527] tracking-tight">{summary.completed_count}</p>
                  <p className="text-[10px] uppercase font-bold text-gray-400 tracking-widest mt-1">สำเร็จแล้ว</p>
                </div>
                <div className="w-px h-10 bg-gray-100" />
                <div className="text-center">
                  <p className="text-3xl font-black text-gray-900 tracking-tight">{summary.progress_percentage}%</p>
                  <p className="text-[10px] uppercase font-bold text-gray-400 tracking-widest mt-1">ความคืบหน้า</p>
                </div>
              </div>
            </div>
            
            <div className="mt-8">
              <div className="flex justify-between items-center mb-2">
                <span className="text-[10px] uppercase font-bold text-gray-400 tracking-widest">ภาพรวมความสำเร็จ</span>
                <span className="text-xs font-bold text-gray-900">{summary.progress_percentage}%</span>
              </div>
              <div className="h-1.5 w-full bg-gray-50 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-red-500 rounded-full transition-all duration-1000 ease-out"
                  style={{ width: `${summary.progress_percentage}%` }}
                />
              </div>
            </div>
          </div>
        )}

        {/* Loading */}
        {isLoading && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="bg-white rounded-2xl p-6 animate-pulse border border-gray-100">
                <div className="flex items-center gap-3 mb-4">
                  <div className="w-12 h-12 bg-gray-200 rounded-full" />
                  <div className="flex-1">
                    <div className="w-32 h-5 bg-gray-200 rounded mb-2" />
                    <div className="w-20 h-3 bg-gray-200 rounded" />
                  </div>
                </div>
                <div className="w-full h-3 bg-gray-200 rounded mt-4" />
              </div>
            ))}
          </div>
        )}

        {/* Empty */}
        {!isLoading && list.length === 0 && (
          <div className="bg-white rounded-2xl p-12 text-center border border-gray-100">
            <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <Award size={40} className="text-gray-400" />
            </div>
            <h3 className="text-xl font-bold text-gray-700 mb-2">ยังไม่มีความสำเร็จ</h3>
            <p className="text-gray-500">ความสำเร็จจะปรากฏที่นี่เมื่อมีภารกิจให้ทำ</p>
          </div>
        )}

        {/* Achievement Grid */}
        {!isLoading && list.length > 0 && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {list.map((item: any) => {
              const info = getConditionInfo(item.condition_type);
              const progress = item.target_value > 0 
                ? Math.min(Math.round((item.current_value / item.target_value) * 100), 100) 
                : 0;

              return (
                <div
                  key={item.achievement_id}
                  onClick={() => handleCardClick(item.achievement_id)}
                  className={`bg-white rounded-[24px] p-6 border transition-all duration-300 cursor-pointer group hover:bg-gray-50/50 ${
                    item.is_completed 
                      ? 'border-green-100 hover:border-green-200' 
                      : 'border-gray-100 hover:border-gray-200'
                  }`}
                >
                  <div className="flex items-start justify-between mb-6">
                    <div 
                      className="w-12 h-12 rounded-2xl flex items-center justify-center transition-transform group-hover:scale-110"
                      style={{ backgroundColor: `${info.color}10`, color: info.color }}
                    >
                      {info.icon ? React.cloneElement(info.icon as React.ReactElement<any>, { className: 'w-6 h-6' }) : <Target size={24} />}
                    </div>
                    {item.is_completed && (
                      <span className={`text-[10px] uppercase font-bold px-2.5 py-1 rounded-full tracking-wider ${
                        item.is_claimed 
                          ? 'bg-gray-100 text-gray-400' 
                          : 'bg-green-100 text-green-600'
                      }`}>
                        {item.is_claimed ? 'รับแล้ว' : 'สิทธิ์คงค้าง'}
                      </span>
                    )}
                  </div>

                  <div className="mb-6">
                    <h3 className="text-base font-bold text-gray-900 mb-1 group-hover:text-[#E33527] transition-colors line-clamp-1">
                      {item.title}
                    </h3>
                    <p className="text-xs text-gray-400 font-normal">{info.label}</p>
                  </div>

                  <div className="space-y-2">
                    <div className="flex justify-between items-end">
                      <span className="text-[10px] uppercase font-bold text-gray-300 tracking-widest">ความก้าวหน้า</span>
                      <span className="text-xs font-bold text-gray-900">
                        {item.current_value} / {item.target_value}
                      </span>
                    </div>
                    <div className="h-1 w-full bg-gray-50 rounded-full overflow-hidden">
                      <div 
                        className="h-full rounded-full transition-all duration-700 ease-out"
                        style={{ 
                          width: `${progress}%`,
                          backgroundColor: item.is_completed ? '#10B981' : info.color 
                        }}
                      />
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Detail Modal */}
      <Modal
        open={isDetailOpen}
        onCancel={() => { setIsDetailOpen(false); setSelectedId(null); }}
        footer={null}
        centered
        width={480}
        zIndex={5000}
        closeIcon={<X size={20} />}
        styles={{ body: { padding: 0 } }}
      >
        {detailLoading && (
          <div className="p-8 flex items-center justify-center">
            <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-[#E33527]" />
          </div>
        )}

        {!detailLoading && detail && (() => {
          const info = getConditionInfo(detail.condition_type);
          const progress = detail.target_value > 0 
            ? Math.min(Math.round((detail.current_value / detail.target_value) * 100), 100) 
            : 0;
          return (
            <div className="font-primary">
              {/* Refined Header */}
              <div className="p-10 pt-12 text-center relative overflow-hidden">
                <div className="absolute top-0 inset-x-0 h-32 bg-gradient-to-b from-gray-50/50 to-transparent pointer-events-none" />
                
                <div className="w-24 h-24 mx-auto mb-6 rounded-[28px] bg-red-50 flex items-center justify-center text-[#E33527] shadow-sm relative z-10">
                  {detail.icon_url ? (
                    <Image src={detail.icon_url} alt={detail.title} width={56} height={56} className="object-contain" unoptimized />
                  ) : (
                    <Trophy size={48} strokeWidth={1.5} />
                  )}
                </div>
                
                <h2 className="text-2xl font-black text-gray-900 mb-2 relative z-10">{detail.title}</h2>
                {detail.description && (
                  <p className="text-gray-500 text-sm font-normal max-w-[280px] mx-auto relative z-10">{detail.description}</p>
                )}
              </div>

              {/* Body */}
              <div className="px-10 pb-10">
                {/* Status Indicator */}
                <div className="flex items-center justify-between mb-8 p-4 bg-gray-50/80 rounded-[20px] border border-gray-50">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-full bg-white flex items-center justify-center shadow-sm" style={{ color: info.color }}>
                      {info.icon ? React.cloneElement(info.icon as React.ReactElement<any>, { size: 16 }) : <Target size={16} />}
                    </div>
                    <div>
                      <p className="text-[10px] uppercase font-bold text-gray-400 tracking-widest leading-none mb-0.5">ประเภท</p>
                      <p className="text-sm text-gray-900 font-bold leading-none">{info.label}</p>
                    </div>
                  </div>
                  <span className={`text-[10px] font-black px-3 py-1.5 rounded-full uppercase tracking-wider ${
                    detail.is_completed 
                      ? detail.is_claimed 
                        ? 'bg-gray-100 text-gray-400' 
                        : 'bg-green-100 text-green-600'
                      : 'bg-orange-100 text-orange-600'
                  }`}>
                    {detail.is_completed ? (detail.is_claimed ? 'CLAIMED' : 'COMPLETED') : 'IN PROGRESS'}
                  </span>
                </div>

                {/* Refined Progress section */}
                <div className="mb-10">
                  <div className="flex justify-between items-end mb-3">
                    <span className="text-[10px] uppercase font-bold text-gray-300 tracking-widest">ความก้าวหน้า</span>
                    <span className="text-sm font-black text-gray-900">
                      {detail.current_value} <span className="text-gray-300 mx-1">/</span> {detail.target_value}
                    </span>
                  </div>
                  <div className="h-2 w-full bg-gray-50 rounded-full overflow-hidden">
                    <div 
                      className="h-full rounded-full transition-all duration-1000 ease-out"
                      style={{ 
                        width: `${progress}%`,
                        backgroundColor: detail.is_completed ? '#10B981' : info.color 
                      }}
                    />
                  </div>
                </div>

                {/* Rewards */}
                {detail.rewards && detail.rewards.length > 0 && (
                  <div className="mb-8">
                    <h3 className="text-[10px] uppercase font-bold text-gray-400 tracking-widest mb-4 flex items-center gap-2">
                       ของรางวัล
                    </h3>
                    <div className="space-y-3">
                      {detail.rewards.map((reward: any) => (
                        <div 
                          key={reward.id} 
                          className="flex items-center justify-between p-4 bg-white rounded-2xl border border-gray-100 shadow-sm"
                        >
                          <div className="flex items-center gap-3">
                            <div className="w-10 h-10 bg-amber-50 rounded-xl flex items-center justify-center p-2">
                              {reward.reward_type === 'coin' ? (
                                <Image src={settings?.coin || '/images/e-coin.png'} alt="เหรียญ" width={24} height={24} unoptimized className="object-contain" />
                              ) : reward.reward_type === 'freecoin' ? (
                                <Image src={settings?.freecoin || '/images/money-bag.png'} alt="ถุงเงิน" width={24} height={24} unoptimized className="object-contain" />
                              ) : (
                                <Gift size={20} className="text-amber-500" strokeWidth={1.5} />
                              )}
                            </div>
                            <div>
                              <p className="text-xs font-bold text-gray-900">
                                {reward.reward_type === 'coin' ? 'เหรียญทอง' : reward.reward_type === 'freecoin' ? 'เหรียญฟรี' : reward.reward_type}
                              </p>
                              <p className="text-[10px] text-gray-400">เข้าบัญชีทันทีเมื่อกดรับ</p>
                            </div>
                          </div>
                          <span className="text-xl font-black text-amber-500">
                            +{reward.reward_amount}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Claim Button */}
                {detail.is_completed && !detail.is_claimed && (
                  <button
                    onClick={() => handleClaim(detail.achievement_id)}
                    disabled={claiming}
                    className="w-full bg-gray-900 !text-white h-14 rounded-2xl font-bold text-base hover:bg-black transition-all disabled:opacity-50 flex items-center justify-center gap-2 shadow-xl shadow-gray-200"
                  >
                    {claiming ? (
                      <div className="animate-spin rounded-full h-5 w-5 border-t-2 border-b-2 border-white" />
                    ) : (
                      <>
                        <Gift size={20} strokeWidth={1.5} />
                        รับรางวัล
                      </>
                    )}
                  </button>
                )}
              </div>
            </div>
          );
        })()}
      </Modal>
    </div>
  );
}

