import { useEffect, useState } from 'react';
import { detectExtension } from "@/utils/securityUtils";

export function useContentProtection(episodeData: any, onBlur?: () => void) {
    const [isFocused, setIsFocused] = useState(true);

    useEffect(() => {
        const disableRightClick = (e: MouseEvent) => {
            e.preventDefault();
        };

        const protectContent = () => {
            const noop = () => { };
            if (typeof window !== "undefined" && process.env.NODE_ENV !== "development") {
                (window as any).console.log = noop;
                (window as any).console.info = noop;
                (window as any).console.warn = noop;
                (window as any).console.error = noop;
                (window as any).console.debug = noop;
            }

            const originalCreateElement = document.createElement.bind(document);
            document.createElement = function (tagName: string) {
                if (typeof tagName === "string" && tagName.toLowerCase() === "iframe") {
                    throw new Error("iframe creation is not allowed on this page");
                }
                return originalCreateElement(tagName);
            } as any;

            const blockIframeInsertion = () => {
                const observer = new MutationObserver((mutations) => {
                    mutations.forEach((mutation) => {
                        mutation.addedNodes.forEach((node) => {
                            if (node.nodeType === 1 && (node as Element).tagName === "IFRAME") {
                                node.parentNode?.removeChild(node);
                            }
                        });
                    });
                });

                observer.observe(document.body, {
                    childList: true,
                    subtree: true,
                });

                return observer;
            };

            const iframeObserver = blockIframeInsertion();

            const originalAppendChild = Node.prototype.appendChild;
            Node.prototype.appendChild = function (this: Node, child: any) {
                if (child?.tagName === "IFRAME") {
                    throw new Error("iframe insertion is not allowed");
                }
                return originalAppendChild.call(this, child);
            } as any;

            const originalInsertBefore = Node.prototype.insertBefore;
            Node.prototype.insertBefore = function (this: Node, newNode: any, refNode: any) {
                if (newNode?.tagName === "IFRAME") {
                    throw new Error("iframe insertion is not allowed");
                }
                return originalInsertBefore.call(this, newNode, refNode);
            } as any;

            const contentElements = document.querySelectorAll(".episode-content");
            contentElements.forEach((element) => {
                try {
                    const innerTextDesc = Object.getOwnPropertyDescriptor(element, "innerText");
                    const textContentDesc = Object.getOwnPropertyDescriptor(element, "textContent");

                    if (!innerTextDesc || innerTextDesc.configurable !== false) {
                        Object.defineProperty(element, "innerText", {
                            get: () => "⚠️ เนื้อหาได้รับการปกป้อง",
                            configurable: true,
                        });
                    }

                    if (!textContentDesc || textContentDesc.configurable !== false) {
                        Object.defineProperty(element, "textContent", {
                            get: () => "⚠️ เนื้อหาได้รับการปกป้อง",
                            configurable: true,
                        });
                    }
                } catch {
                }
            });

            return () => {
                iframeObserver.disconnect();
            };
        };

        const handleWindowBlur = () => {
            if (onBlur) onBlur();
            setIsFocused(false);
        };

        const handleWindowFocus = () => {
            setIsFocused(true);
        };

        const handleKeyDown = (event: KeyboardEvent) => {
            if (
                event.key === 'F12' ||
                event.ctrlKey ||
                event.metaKey ||
                event.key === 'PrintScreen' ||
                event.keyCode === 44
            ) {
                event.preventDefault();
                handleWindowBlur();
                setTimeout(() => {
                    handleWindowFocus();
                }, 2000);
            }
        };

        const handleRightClick = (event: Event) => {
            event.preventDefault();
        };

        window.addEventListener('blur', handleWindowBlur);
        window.addEventListener('focus', handleWindowFocus);
        window.addEventListener('keydown', handleKeyDown);
        window.addEventListener('contextmenu', handleRightClick);

        document.addEventListener("contextmenu", disableRightClick);

        const timer = setTimeout(() => {
            protectContent();
        }, 1000);

        // Assuming detectExtension is a utility that returns an observer or similar cleanup
        detectExtension();

        return () => {
            window.removeEventListener('blur', handleWindowBlur);
            window.removeEventListener('focus', handleWindowFocus);
            window.removeEventListener('keydown', handleKeyDown);
            window.removeEventListener('contextmenu', handleRightClick);

            document.removeEventListener("contextmenu", disableRightClick);
            clearTimeout(timer);
        };
    }, [episodeData, onBlur]);

    return { isFocused, setIsFocused };
}

import { useCallback, useEffect, useMemo, useState } from "react";
import {
  evaluateAndTrackFreeReadQuota,
  hasShownFirstTopupPrompt,
  markFirstTopupPromptShown,
  mergeGuestQuotaToUser,
  type FreeQuotaBlockReason,
} from "@/utils/readFreeQuota";

type UseReadFreeQuotaInput = {
  bookId: string;
  episodeId: string;
  isLoggedIn: boolean;
  userId?: string | number | null;
  canTrack: boolean;
  isEpisodeOwned: boolean;
  guestLimit?: number;
  memberLimit?: number;
};

type UseReadFreeQuotaResult = {
  isBlocked: boolean;
  reason: FreeQuotaBlockReason;
  currentCount: number;
  limit: number;
  alreadyRead: boolean;
  hasShownTopupPrompt: boolean;
  markTopupPromptShown: () => void;
};

const DEFAULT_GUEST_LIMIT = 10;
const DEFAULT_MEMBER_LIMIT = 40;

export function useReadFreeQuota({
  bookId,
  episodeId,
  isLoggedIn,
  userId,
  canTrack,
  isEpisodeOwned,
  guestLimit = DEFAULT_GUEST_LIMIT,
  memberLimit = DEFAULT_MEMBER_LIMIT,
}: UseReadFreeQuotaInput): UseReadFreeQuotaResult {
  const [state, setState] = useState<Omit<UseReadFreeQuotaResult, "markTopupPromptShown">>({
    isBlocked: false,
    reason: null,
    currentCount: 0,
    limit: isLoggedIn ? memberLimit : guestLimit,
    alreadyRead: false,
    hasShownTopupPrompt: false,
  });

  const userKey = useMemo(() => (userId === null || userId === undefined ? "" : String(userId)), [userId]);

  useEffect(() => {
    if (!isLoggedIn || !userKey) return;
    mergeGuestQuotaToUser(userKey);
  }, [isLoggedIn, userKey]);

  useEffect(() => {
    const nextLimit = isLoggedIn ? memberLimit : guestLimit;
    if (!bookId || !episodeId || !canTrack) {
      setState((prev) => ({
        ...prev,
        isBlocked: false,
        reason: null,
        limit: nextLimit,
      }));
      return;
    }

    const result = evaluateAndTrackFreeReadQuota({
      bookId,
      episodeId,
      isLoggedIn,
      userId: userKey || null,
      guestLimit,
      memberLimit,
      isEpisodeOwned,
    });

    const shown = isLoggedIn
      ? hasShownFirstTopupPrompt({ bookId, userId: userKey || null })
      : false;

    setState({
      isBlocked: result.blocked,
      reason: result.reason,
      currentCount: result.currentCount,
      limit: result.limit,
      alreadyRead: result.alreadyRead,
      hasShownTopupPrompt: shown,
    });
  }, [bookId, canTrack, episodeId, guestLimit, isEpisodeOwned, isLoggedIn, memberLimit, userKey]);

  const markTopupPromptShown = useCallback(() => {
    if (!isLoggedIn || !userKey || !bookId) return;
    markFirstTopupPromptShown({ bookId, userId: userKey });
    setState((prev) => ({ ...prev, hasShownTopupPrompt: true }));
  }, [bookId, isLoggedIn, userKey]);

  return {
    ...state,
    markTopupPromptShown,
  };
}

'use client';

import React, { createContext, useContext, useEffect, useState } from 'react';
import { io, Socket } from 'socket.io-client';
import { useAuthStore } from '@/stores/authStore';
import Cookies from 'js-cookie';
import { parseJwtToken } from '@/utils/jwtParser';

const isSessionIdUnknownError = (message: string | undefined) =>
  typeof message === 'string' && message.toLowerCase().includes('session id unknown');

interface SocketContextType {
  socket: Socket | null;
  isConnected: boolean;
}

const SocketContext = createContext<SocketContextType>({
  socket: null,
  isConnected: false,
});

export const useSocket = () => {
  return useContext(SocketContext);
};

export default function SocketProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const { token: authToken, user } = useAuthStore() as any;
  
  // Calculate dependencies at component level
  const resolvedUserId = user?.user_id || (user as any)?.id || (user as any)?.userId;
  const fullname = user?.fullname;

  useEffect(() => {
    // ใช้ URL เดียวกับ API โดย fallback ไปที่ค่า default ถ้าไม่มี env
    const socketUrl = process.env.NEXT_PUBLIC_API_BASE_URL || 'http://192.168.220.214:3331';
    
    // Retrieve token from store or cookie fallback
    let token = authToken;
    let currentUser = user;

    if (!token && typeof window !== 'undefined') {
      token = parseJwtToken(Cookies.get('token')) || null;
    }
    if (token) {
         token = token.replace(/^Bearer\s+/i, '').trim();
    } 

    const currentUserId = currentUser?.user_id || (currentUser as any)?.id || (currentUser as any)?.userId;
    
    // 1. If no token (Guest) or waiting for user ID resolution, do not connect socket.
    if (!token || !currentUserId) {
        setSocket(null); // Ensure we don't hold onto a stale socket
        return;
    }

    /* console.log('Socket Initial Query:', {
      user_id: currentUserId || 'undefined',
      'fullname': currentUser?.fullname || 'undefined'
    }); */

    // 2. Initialize Socket
    const socketInstance = io(socketUrl, {
      transports: ['websocket'], 
      reconnection: true,
      reconnectionAttempts: 10,
      reconnectionDelay: 2000,
      reconnectionDelayMax: 30000,
      timeout: 10000,
      forceNew: false,
      auth: (cb) => {
        // ⚡ Dynamic Auth: Fetch latest token on every connection/reconnection attempt
        let latestToken = useAuthStore.getState().token;
        if (!latestToken) {
            latestToken = parseJwtToken(Cookies.get('token')) || null;
        }
        cb({ token: latestToken });
      },
      query: {
        user_id: currentUserId || 'undefined',
        fullname: currentUser?.fullname || 'undefined',
      }
    });

    socketInstance.on('connect', () => {
      setIsConnected(true);
    });

    socketInstance.on('disconnect', (reason) => {
      setIsConnected(false);
      if (reason === "io server disconnect") socketInstance.connect();
    });

    socketInstance.on('connect_error', (err) => {
        setIsConnected(false);
        if (isSessionIdUnknownError(err?.message)) {
          socketInstance.io.opts.reconnection = false;
          socketInstance.disconnect();
        }
    });

    // Handle force_refresh event
    socketInstance.on('force_refresh', async () => {
        // console.log("📢 Received force_refresh:", data);
        try {
            let currentToken = useAuthStore.getState().token;
            if (!currentToken) currentToken = parseJwtToken(Cookies.get('token')) || null;

            if (currentToken) {
                 const refreshToken = (await import('@/services/apiServices')).refreshToken;
                 const newTokenResult = await refreshToken(currentToken);
                 const newToken = newTokenResult?.data?.token || newTokenResult?.token || newTokenResult?.data;

                 if (typeof newToken === 'string') {
                     useAuthStore.getState().updateToken(newToken);
                     // console.log("✅ Token refreshed successfully via socket event");
                 }
            }
        } catch (error) {
            console.error("❌ Failed to refresh token via socket:", error);
        }
    });

    setSocket(socketInstance);

    return () => {
      socketInstance.disconnect();
    };
  }, [authToken, resolvedUserId, fullname]);

  // Handle visibility separate from socket creation
  useEffect(() => {
      if (!socket) return;

      const onVisibilityChange = () => {
        if (document.visibilityState === 'visible' && !socket.connected) {
          const latestUser = useAuthStore.getState().user as any;
          const latestToken = useAuthStore.getState().token || parseJwtToken(Cookies.get('token')) || null;
          const latestUserId = latestUser?.user_id || latestUser?.id || latestUser?.userId;
          if (latestToken && !latestUserId) return;
          if ((socket.io.opts.reconnection ?? true) === false) return;
          socket.connect();
        }
      };

      document.addEventListener('visibilitychange', onVisibilityChange);
      return () => {
          document.removeEventListener('visibilitychange', onVisibilityChange);
      };
  }, [socket]);

  // 🔧 Auto-heal: Recovery for missing user_id in stale localStorage data
  useEffect(() => {
    if (authToken && user) {
        // If user logged in but missing ID, force re-parse of token
        if (!user.user_id && !(user as any).id && !(user as any).userId) {
             // console.log("🔧 Auto-healing: Triggering token update to recover missing user_id");
             useAuthStore.getState().updateToken(authToken);
        }
    }
  }, [authToken, user]);

  return (
    <SocketContext.Provider value={{ socket, isConnected }}>
      {children}
    </SocketContext.Provider>
  );
}
